// Package client is a Go client for the OpenHands Software Agent SDK "agent server"
// REST API (pinned in agent/image/Dockerfile) plus a small WebSocket event consumer.
//
// The REST client (client.gen.go) is generated by oapi-codegen from openapi.yaml, a
// trimmed OpenAPI 3.0 document that covers only the endpoints yari drives: health,
// ready, server info, start/get/delete conversation, send message, pause, run
// (resume), interrupt, and event list/count. openapi.yaml is itself derived from the
// full OpenAPI 3.1 document of the pinned server image by ./trimspec, because the
// full document (about 700 KB, 500+ schemas, 3.1-only constructs) is not practical to
// generate from.
//
// # Regenerating
//
// Run these from the repository root when the pinned agent-server image changes:
//
//	# 1. Start the new image and save its full spec (any session key works):
//	docker run -d --rm --name oh-spec -p 127.0.0.1:18000:8000 \
//	    -e OH_SESSION_API_KEYS_0=spec-only-placeholder yari-agent:dev
//	curl -fsS http://127.0.0.1:18000/openapi.json -o /tmp/openhands-openapi-full.json
//	docker rm -f oh-spec
//
//	# 2. Trim it to openapi.yaml, then regenerate client.gen.go:
//	go run ./internal/agent/openhands/client/trimspec \
//	    -in /tmp/openhands-openapi-full.json -out internal/agent/openhands/client/openapi.yaml
//	go generate ./internal/agent/openhands/client
//
// Authentication is not part of the generated code: use [NewAuthedClient], which adds
// the X-Session-API-Key header to every request.
package client

//go:generate go tool oapi-codegen -config oapi-codegen.yaml openapi.yaml
